	if _, err := s.StartBatch("s1", "B1"); err != nil {
		t.Fatal(err)
	}
	if _, err := s.AddFeeding("x2", "B1", "M9", "10", time.Now(), "张三"); !errors.Is(err, ErrMaterialNotInRecipe) {
		t.Fatalf("应失败，得到 %v", err)
