	}); err != nil {
		fmt.Fprintf(os.Stderr, "helper register: %v\n", err)
		os.Exit(1)
	}
	if _, err := s.CreateBatch("b-"+id, "B1", "R1", "v1", 10); err != nil {
		fmt.Fprintf(os.Stderr, "helper create: %v\n", err)
		os.Exit(1)
	}
